# The opening movie's art pack: the eight movie backdrops and figures (art/promo/trailers/art/), the three chapter logos
# (art/ruinfall/chapters.py) and the pre-patch logo (art/ruinfall/prepatch_logo.py), as ART.opening(key).
# Usage: python3 art/promo/trailers/pack.py  ->  src/art_ruinfall_opening.js (do not edit that file by hand)
import json, os, re
H = os.path.dirname(os.path.abspath(__file__)); ROOT = os.path.join(H, '..', '..', '..')
NEW = ['rf_torn_land', 'rf_war_field', 'rf_ledger', 'rf_spire_night', 'rf_crown', 'rf_note', 'rf_wound_sky', 'rf_ruin_eye']
def svg(p):
    s = open(os.path.join(ROOT, p)).read().strip()
    s = re.sub(r'<\?xml[^>]*\?>\s*', '', s)
    return re.sub(r'>\s+<', '><', s)  # the whitespace between tags only, never inside text
pack = {k: svg(f'art/promo/trailers/art/{k}.svg') for k in NEW}
pack.update({f'ch{n}': svg(f'art/ruinfall/chapter{n}.svg') for n in (1, 2, 3)})
pack['prepatch'] = svg('art/ruinfall/prepatch.svg')
out = ('// The Ruinfall Saga opening movie art, generated by art/promo/trailers/pack.py; do not edit by hand.\n'
       '(function (root) { root.ART = root.ART || {}; root.ART.openingArt = ' + json.dumps(pack, separators=(',', ':')) + '; root.ART.opening = (k) => root.ART.openingArt[k] || ""; })'
       "(typeof window !== 'undefined' ? window : globalThis);\n")
open(os.path.join(ROOT, 'src', 'art_ruinfall_opening.js'), 'w').write(out)
print('src/art_ruinfall_opening.js', len(out) // 1024, 'KB')
